// Regression fixture for #78 — the load()-level re-mediation backstop.
//
// Every specifier below is spelled `raw:<builtin>`, which names nothing capwall mediates. The
// app has registered a loader hook (see backstop-app.mjs) that short-circuits that spelling
// straight to the raw `node:<builtin>` URL, so capwall's `resolve` is NEVER consulted for any of
// these imports — Node runs the most recently registered hook first. The only thing left between
// this package and the raw builtin is capwall's `load` hook, which refuses to pass a bare
// `node:<mediated>` URL through and serves the shim-backed synthetic source instead.
//
// That backstop can only run if the URL is not already in the ESM module cache, which is exactly
// what capwall's own `real-builtins.cjs` capture buys (a CJS require does not populate the ESM
// cache). Before #78 capwall ESM-imported its real builtins and every line below reached the raw
// module.
//
// Inert per AGENTS.md § 8: it reads its own data.txt and otherwise only compares namespace
// identities. Nothing is spawned, connected or written.

import { fileURLToPath } from "node:url";

const DATA = fileURLToPath(new URL("./data.txt", import.meta.url));

/** Every builtin capwall mediates, in registry order. Both spellings share one shim. */
const MEDIATED = [
  "fs",
  "fs/promises",
  "net",
  "http",
  "https",
  "tls",
  "http2",
  "dgram",
  "child_process",
  "worker_threads",
  "vm",
  "module",
];

/**
 * Did `ns` come back as capwall's shim, or as the raw builtin?
 *
 * `process.getBuiltinModule` (Node ≥20.16 / ≥22.3) is the only reference to the REAL module a
 * mediated process still has, which is what makes it the discriminator here. Where it is absent
 * the fixture says so rather than guessing — the stderr re-mediation warning is capwall's own
 * version-independent signal and the test asserts that separately.
 */
function classify(ns, spec) {
  if (typeof process.getBuiltinModule !== "function") return "UNTESTABLE";
  const real = process.getBuiltinModule("node:" + spec);
  return ns.default === real ? "RAW" : "SHIM";
}

export async function run() {
  const out = [];
  for (const spec of MEDIATED) {
    try {
      out.push(`${spec}:${classify(await import("raw:" + spec), spec)}`);
    } catch (err) {
      out.push(`${spec}:ERR:${(err && err.message) || err}`);
    }
  }

  // Identity is necessary but not sufficient: prove the re-mediated module actually ENFORCES.
  // Under the deny-all policy this fixture runs with, a real fs read of its own data file must
  // come back as a CapabilityError attributed to this package.
  const fs = await import("raw:fs");
  try {
    out.push(`enforce-fs:RAW:${fs.readFileSync(DATA, "utf8").trim()}`);
  } catch (err) {
    out.push(
      err && err.name === "CapabilityError"
        ? `enforce-fs:BLOCKED:${err.pkg}`
        : `enforce-fs:ERR:${err && err.code}`,
    );
  }

  // …and that the re-mediated `node:module` still carries #61's loader-hook gate, which is the
  // one mediated specifier whose shim is a Proxy over a class rather than a plain namespace.
  const mod = await import("raw:module");
  try {
    mod.register("data:text/javascript,export const resolve=(s,c,n)=>n(s,c);", import.meta.url);
    out.push("enforce-module:REGISTERED");
  } catch (err) {
    out.push(
      err && err.name === "CapabilityError"
        ? `enforce-module:BLOCKED:${err.pkg}`
        : `enforce-module:ERR:${err && err.code}`,
    );
  }
  return out;
}
